const modelCatalogRequests=new Map(),modelPreferenceSaves=new Map();
const composerCatalogKey=(provider,projectId)=>state.modelCatalogRevision+':'+modelCatalogKey(provider,projectId);
function composerModelContext(side=false){
  const data=side?state.sideThread:state.thread,provider=modelProviders().find(p=>p.id===composerProviderId(side));
  const threadId=(side?state.sideThreadId:state.threadId)||'',choiceKey=threadId+':'+provider?.id;
  const entry=state.modelCatalogs[composerCatalogKey(provider,state.projectId)];
  return {data,provider,threadId,choiceKey,entry,model:resolveCodexModel({provider,thread:data?.thread,runs:data?.runs,catalog:entry?.catalog,choice:state.modelChoices[choiceKey]})};
}
async function ensureModelCatalog(provider,projectId=state.projectId,{retry=false}={}){
  if(!isCodexProvider(provider)||!projectId)return;
  const key=composerCatalogKey(provider,projectId);
  if(modelCatalogRequests.has(key))return modelCatalogRequests.get(key);
  if(!retry&&state.modelCatalogs[key])return state.modelCatalogs[key].catalog;
  state.modelCatalogs[key]={status:'loading'};
  const request=(async()=>{
    try{const catalog=await api('/api/providers/'+encodeURIComponent(provider.id)+'/models?projectId='+encodeURIComponent(projectId));state.modelCatalogs[key]={status:'ready',catalog};return catalog;}
    catch(error){state.modelCatalogs[key]={status:'error',error:error.message};return undefined;}
    finally{modelCatalogRequests.delete(key);renderMain(true);renderPanel(true);}
  })();
  modelCatalogRequests.set(key,request);
  return request;
}
function codexModelPicker(side=false){
  const {provider,entry,model,choiceKey}=composerModelContext(side);if(!isCodexProvider(provider))return '';
  if(!entry){queueMicrotask(()=>ensureModelCatalog(provider));}
  const id=side?'side-codex-model-select':'codex-model-select',label=side?'线程 Codex 模型':'项目 Codex 模型';
  if(!entry||entry.status==='loading')return `<select id="${id}" aria-label="${label}" disabled><option>${esc(model||'读取模型…')}</option></select>`;
  const custom=entry.catalog?.supportsDiscovery===false,options=codexModelOptions(entry.catalog,model);
  if(custom||entry.status==='error'||!options.length)return `<input id="${id}" class="codex-model-input" aria-label="${label}" placeholder="${custom?'模型 ID':'模型 ID（原生默认）'}" title="${esc(custom?'填写此连接支持的模型 ID':entry.error||'未返回模型目录，可填写模型 ID')}" maxlength="200" value="${esc(state.modelInputDrafts[choiceKey]??model)}">${!custom?iconBtn('retry-codex-models','重新读取模型','refresh',`data-side="${side}"`):''}`;
  return `<select id="${id}" aria-label="${label}" title="${esc(model)}">${!model?'<option value="">原生默认模型</option>':''}${options.map(m=>`<option value="${esc(m.value)}" ${m.value===model?'selected':''}>${esc(m.label)}</option>`).join('')}</select>`;
}
async function saveComposerModel(value,side=false){
  const {threadId,provider,choiceKey}=composerModelContext(side);if(!threadId||!isCodexProvider(provider))return;
  const model=value.trim();if(model.length>200||/[\u0000-\u001f\u007f]/.test(model))throw new Error('请输入有效的模型 ID');
  state.modelChoices[choiceKey]=model;
  const pending=(modelPreferenceSaves.get(choiceKey)||Promise.resolve()).catch(()=>{}).then(()=>api('/api/threads/'+encodeURIComponent(threadId)+'/model',{method:'PATCH',body:JSON.stringify({providerId:provider.id,model})}));
  modelPreferenceSaves.set(choiceKey,pending);
  if(side)renderPanel(true);else renderMain(true);
  try{const result=await pending;if(state.modelInputDrafts[choiceKey]?.trim()===model)delete state.modelInputDrafts[choiceKey];for(const data of [state.thread,state.sideThread])if(data?.thread?.id===threadId)data.thread=result.thread||data.thread;}
  catch(error){if(state.modelChoices[choiceKey]===model)delete state.modelChoices[choiceKey];throw error;}
  finally{if(modelPreferenceSaves.get(choiceKey)===pending)modelPreferenceSaves.delete(choiceKey);renderMain(true);renderPanel(true);}
}
