function toast(message,error=false){const node=document.createElement('div');node.className='toast'+(error?' error':'');node.innerHTML=icon(error?'warning':'check')+`<span>${esc(message)}</span>`;$('#toasts').append(node);while($('#toasts').children.length>2)$('#toasts').firstElementChild.remove();setTimeout(()=>node.remove(),5000);}
async function api(path,options={}){const controller=new AbortController();const timeout=setTimeout(()=>controller.abort(),options.timeoutMs||60000);try{const r=await fetch(path,{...options,headers:{'Content-Type':'application/json',...(options.headers||{})},signal:controller.signal});const text=await r.text();let result;try{result=text?JSON.parse(text):{};}catch{throw new Error('服务返回了无法读取的结果');}if(!r.ok)throw Object.assign(new Error(result.error||`请求失败（${r.status}）`),{status:r.status});return result;}catch(e){if(e.name==='AbortError')throw new Error('请求超时，请稍后再试');throw e;}finally{clearTimeout(timeout);}}
