document.addEventListener('input',e=>{if(e.target.matches('input#codex-model-select,input#side-codex-model-select')){const c=composerModelContext(e.target.id==='side-codex-model-select');state.modelInputDrafts[c.choiceKey]=e.target.value;return;}if(e.target.closest('.question-form'))captureQuestionInput(e.target);if(e.target.closest('#provider-form'))updateProviderFields();if(['composer','side-composer'].includes(e.target.id)){const side=e.target.id==='side-composer',key=(side?state.sideThreadId:state.threadId)||state.projectId||'new';state.drafts[key]=e.target.value;autoGrow(e.target);const actions=$(side?'#side-composer-actions':'#composer-actions');if(actions)actions.innerHTML=composerButtons(side,runsFor(side?state.sideThread:state.thread).length>0,Boolean(e.target.value.trim()||state.attachments[key]?.length));}if(e.target.closest('#project-form'))updateProjectSubmit();if(e.target.id==='project-search'){state.projectSearch=e.target.value;keepFocus(renderSidebar);}if(e.target.id==='benchmark-search'){state.benchmarkQuery=e.target.value;renderPanel();}});
document.addEventListener('change',async e=>{try{if(e.target.closest('.question-form')){captureQuestionInput(e.target);return;}if(['codex-model-select','side-codex-model-select'].includes(e.target.id)){await saveComposerModel(e.target.value,e.target.id==='side-codex-model-select');return;}if(e.target.id==='mcp-transport'){updateConnectorFields();return;}if(e.target.id==='integration-project-select'){await selectProject(e.target.value);return;}if(e.target.id==='provider-type'){updateProviderFields();return;}if(['default-permission-setting','appearance-setting'].includes(e.target.id)){const key=e.target.id==='appearance-setting'?'appearance':'defaultPermissionMode';await saveGlobalSetting(key,e.target.value);return;}if(['main-attachment','side-attachment'].includes(e.target.id)){await stageAttachments(e.target,e.target.id==='side-attachment');return;}if(['permission-select','side-permission-select'].includes(e.target.id)){const side=e.target.id==='side-permission-select',key=(side?state.sideThreadId:state.threadId)||state.projectId||'new';state.permissions[key]=e.target.value;toast(e.target.value==='auto'?'Auto：自动读写、建模和运行项目内命令；额外权限按原生策略询问，桌面操作单独授权。':'Manual：项目写入、模型变更与仿真将请求批准。');if(side)renderPanel(true);else renderMain(true);return;}if(e.target.id==='provider-select'){state.providerId=e.target.value;renderMain(true);}if(e.target.id==='side-provider-select'){state.sideProviderId=e.target.value;state.workerProviders[state.sideThreadId]=e.target.value;renderPanel(true);}if(e.target.id==='benchmark-category'){state.benchmarkCategory=e.target.value;renderPanel();}if(e.target.id==='knowledge-upload'){const f=e.target.files?.[0];if(!f)return;if(f.size>2*1024*1024)throw new Error('单份资料请控制在 2 MB 以内');const text=await f.text();if(text.includes('\u0000'))throw new Error('请选择可读取的纯文本文件');$('#knowledge-name').value=f.name;$('#knowledge-content').value=text;}}catch(err){toast(err.message,true);}});
document.addEventListener('focusout',e=>{if(!e.target.matches('input#codex-model-select,input#side-codex-model-select'))return;const field=e.target;queueMicrotask(()=>{if(!field.isConnected)return;const c=composerModelContext(field.id==='side-codex-model-select'),draft=state.modelInputDrafts[c.choiceKey];if(draft!==undefined&&draft.trim()!==state.modelChoices[c.choiceKey])field.dispatchEvent(new Event('change',{bubbles:true}));});});
document.addEventListener('keydown',e=>{if(e.key==='Enter'&&e.target.matches('input#codex-model-select,input#side-codex-model-select')){e.preventDefault();e.target.dispatchEvent(new Event('change',{bubbles:true}));return;}if((e.metaKey||e.ctrlKey)&&e.key===','){e.preventDefault();openGlobalSettings('general').catch(err=>toast(err.message,true));return;}if(e.key==='Escape'){if(state.modal)closeModal();else if(state.view==='settings'){e.preventDefault();closeGlobalSettings();return;}else if(state.sidebarOpen){state.sidebarOpen=false;render();}}if(['composer','side-composer'].includes(e.target.id)&&e.key==='Enter'&&!e.shiftKey&&!e.isComposing){e.preventDefault();$(e.target.id==='side-composer'?'#side-composer-form':'#composer-form').requestSubmit();}if(e.target.closest('.graph-node')&&(e.key==='Enter'||e.key===' ')){e.preventDefault();openNode(e.target.closest('.graph-node').dataset.id);}if(state.modal&&e.key==='Tab'){const focusable=$$('button:not([disabled]),a[href],input:not([disabled]),textarea:not([disabled]),select:not([disabled]),[tabindex="0"]',$('.modal'));const first=focusable[0],last=focusable.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}}});


const busyStatuses=['queued','running','waiting_approval','awaiting_approval','pending','waiting'];
function runsFor(data){return(data?.runs||[]).filter(r=>busyStatuses.includes(r.status));}
function workerThreads(){return(state.projectThreads.length?state.projectThreads:state.data.threads.filter(t=>t.projectId===state.projectId)).filter(t=>t.id!==state.threadId&&t.kind!=='coordinator');}
function threadExecutionStatus(t){return resolveThreadExecutionStatus(t,{projectThreads:state.projectThreads,mainDetail:state.thread,sideDetail:state.sideThread,sideThreadId:state.sideThreadId,approvals:state.data.approvals||[]});}
function threadGroup(t){const status=threadExecutionStatus(t);if(['waiting_approval','awaiting_approval'].includes(status)||state.data.approvals.some(a=>a.status==='pending'&&a.threadId===t.id))return'waiting';if(status==='waiting_tasks')return'tasks';if(['waiting_job','preparing_environment'].includes(status))return'jobs';if(busyStatuses.includes(status)||['reviewing','summarizing','executing'].includes(status))return'working';if(status==='completed')return'resolved';if(['blocked','failed','cancelled','canceled','interrupted'].includes(status))return'waiting';return'idle';}
function taskReviewLabel(t){const current={...t,...state.projectThreads.find(item=>item.id===t.id)};return taskReviewPresentation(current,threadExecutionStatus(current)).label;}
function threadChip(t){const review=taskReviewLabel(t);return `<button class="thread-chip" data-action="select-thread" data-id="${esc(t.id)}"><span class="thread-state-dot ${threadGroup(t)}"></span><strong>${esc(t.title)}</strong><span>${esc(statusText(threadExecutionStatus(t)))}${review?' · '+esc(review):''}</span>${icon('chevron')}</button>`;}
function rememberDetailOrigin(element){if(state.detailOrigin&&element?.closest('#workspace-panel')&&!element.closest('.worker-messages,.worker-header,.worker-composer'))return;state.nextDetailOrigin=chatDetailOrigin({projectId:state.projectId,mainThreadId:state.threadId,sideThreadId:state.sideThreadId,sideThreadTitle:state.sideThread?.thread?.title,fromThread:Boolean(element?.closest('.worker-messages,.worker-header,.worker-composer'))});}
async function askAgentFromDetail(text){const projectId=state.projectId,target=detailPromptDraft({origin:state.detailOrigin,projectId,mainThreadId:state.threadId,drafts:state.drafts,text});state.drafts[target.threadId]=target.draft;await returnToOriginChat();if(state.projectId!==projectId)return;if(target.side&&state.sideThreadId===target.threadId){renderPanel(true);requestAnimationFrame(()=>$('#side-composer')?.focus());}else{renderMain(true);requestAnimationFrame(()=>$('#composer')?.focus());}}
async function returnToOriginChat(){const origin=state.detailOrigin;state.detailOrigin=null;state.nextDetailOrigin=null;state.workbenchFocus=false;if(origin?.projectId===state.projectId&&origin.threadId&&origin.threadId!==state.threadId){await selectThread(origin.threadId);return;}state.panelOpen=false;state.sideThreadId=null;syncLocation();render();}
function openPane(name){const detail=['professional','library','engineering-plan','model','engineering','engineering-records','computer'].includes(name);if(detail){state.detailOrigin=state.nextDetailOrigin||state.detailOrigin||chatDetailOrigin({projectId:state.projectId,mainThreadId:state.threadId,sideThreadId:state.sideThreadId,sideThreadTitle:state.sideThread?.thread?.title,fromThread:state.panel==='thread'});state.nextDetailOrigin=null;}else{state.detailOrigin=null;state.nextDetailOrigin=null;}state.panel=name;state.panelOpen=true;state.sidebarOpen=false;if(!detail&&name!=='thread')state.sideThreadId=null;syncLocation();render();}
async function loadProjectThreads(){const id=state.projectId;if(!id)return;const r=await api('/api/projects/'+encodeURIComponent(id)+'/threads');if(id!==state.projectId)return;state.projectThreads=r.threads||[];state.threadId=r.coordinatorThreadId||project()?.coordinatorThreadId||state.projectThreads.find(t=>t.kind==='coordinator')?.id||state.projectThreads.find(t=>!t.parentThreadId)?.id||null;}
async function loadMainThread(){if(!state.threadId)return;const id=state.threadId;const r=await api('/api/threads/'+encodeURIComponent(id));if(id===state.threadId)state.thread=r;}
function threadGroupKey(projectId,group){return JSON.stringify([projectId||'',group]);}
function overviewPane(){const all=presentationThreads(state.thread).filter(t=>t.projectId===state.projectId),openGroups=Object.fromEntries(['attention','working','idle','resolved'].filter(group=>Object.hasOwn(state.threadGroupOpen,threadGroupKey(state.projectId,group))).map(group=>[group,state.threadGroupOpen[threadGroupKey(state.projectId,group)]]));return `<div class="pane-heading"><h2>Threads</h2>${btn('new-thread','新建 Thread','plus','compact')}</div>${renderThreadsOverview(all,{projectId:state.projectId,mainThreadId:state.threadId,statusFor:threadExecutionStatus,pendingApprovalFor:t=>pendingApprovals().some(a=>a.threadId===t.id),openGroups})}`;}
function currentMentionThreads(){return presentationThreads(state.thread).filter(t=>t.projectId===state.projectId).map(t=>({...t,executionStatus:threadExecutionStatus(t)}));}
function refreshChatMentions(root){if(root&&state.projectId)enrichThreadMentions(root,{threads:currentMentionThreads().filter(t=>t.id!==state.threadId&&t.kind!=='coordinator'),projectId:state.projectId,allowTitleMatches:true});}
function inlineThreadLink(threadId,title){const thread=currentMentionThreads().find(t=>t.id===threadId),view=thread&&threadMentionView(thread);if(!view)return `<span>${esc(title||thread?.title||'Thread')}</span>`;return `<button type="button" class="thread-mention" data-action="select-thread" data-id="${esc(threadId)}" data-thread-indicator="${esc(view.indicator)}" data-thread-status="${esc(view.executionStatus)}" title="${esc(view.ariaLabel)}" aria-label="${esc(view.ariaLabel)}"><span class="thread-mention-indicator indicator-${esc(view.indicator)}" aria-hidden="true">${({spinner:'',clock:'◷',approval:'!',check:'✓',error:'!',idle:'·'})[view.indicator]}</span><span class="thread-mention-title">${esc(title||view.title)}</span></button>`;}

async function loadEngineeringPlan(){const id=state.projectId;if(!id||state.engineeringPlan.loading)return;state.engineeringPlan={...state.engineeringPlan,for:id,loading:true,error:''};try{const data=await api('/api/projects/'+encodeURIComponent(id)+'/engineering-plan');if(state.projectId===id)state.engineeringPlan={for:id,data:data.plan||data,error:'',loading:false};}catch(error){if(state.projectId===id)state.engineeringPlan={for:id,data:null,error:error.message,loading:false};}renderPanel(true);}

function workerView(){const d=state.sideThread,t=d?.thread;if(!d)return '<div class="pane-loading"><span class="pulse"></span>读取线程…</div>';const approvals=(d.approvals||[]).filter(a=>a.status==='pending');return `<div class="worker-header">${renderTaskBreadcrumb(t.id,presentationThreads(d),state.threadId)}<div class="row between"><h2>${esc(t.title)}</h2>${statusBadge(threadExecutionStatus(t))}</div>${taskReviewLabel(t)?`<p class="worker-review-state">${esc(taskReviewLabel(t))}</p>`:''}</div><div class="worker-messages">${conversationRows(d)}${approvals.map(approvalView).join('')}</div><div class="worker-composer">${composer(true)}</div>`;}
function libraryPane(){const files=state.knowledgeFor===state.projectId?state.knowledge:[],artifacts=state.data.artifacts.filter(a=>a.projectId===state.projectId);return `<div class="pane-heading"><h2>Library</h2>${btn('upload-knowledge','添加','plus','compact')}</div><div class="library-tabs">${[['all','全部'],['knowledge','项目资料'],['artifacts','产物']].map(([id,label])=>`<button data-action="library-${id}" class="${state.libraryFilter===id?'active':''}">${label}</button>`).join('')}</div><div class="library-table"><div class="library-table-head"><span>名称</span><span>修改时间</span><span>类型</span></div>${state.libraryFilter!=='artifacts'?files.map(f=>`<div class="library-file-row"><button data-action="read-knowledge" data-id="${esc(f.id)}">${icon('file')}<span>${esc(f.name)}</span></button><span>${fmtDate(f.createdAt)}</span><span>资料</span>${iconBtn('delete-knowledge','删除资料','trash',`data-id="${esc(f.id)}"`)}</div>`).join(''):''}${state.libraryFilter!=='knowledge'?artifacts.map(a=>`<div class="library-file-row"><button data-action="read-artifact" data-id="${esc(a.id)}">${icon('file')}<span>${esc(a.name||a.path)}</span></button><span>${fmtDate(a.createdAt)}</span><span>${esc((a.name||a.path||'').split('.').at(-1)?.slice(0,6).toUpperCase()||'文件')}</span><span></span></div>`).join(''):''}${!files.length&&!artifacts.length?'<div class="library-empty">项目资料和线程产物会保存在这里。</div>':''}</div>`;}
function toolsPane(){if(state.browseTools)return `<button class="work-catalog-back" data-action="work-context">‹ 返回当前工作</button>`+renderToolHub({registry:state.integrations.for===state.projectId?state.integrations.data?.registry:null,status:state.integrations.status,error:state.integrations.error,stage:state.capabilityStage});const active=workerThreads().filter(t=>['working','tasks','jobs','waiting'].includes(threadGroup(t))),data=state.sideThread||state.thread,rows=data?presentationRows(data).filter(r=>r.kind==='run'):[],latest=rows.at(-1),assets=summarizeChatArtifacts(state.data.artifacts,{projectId:state.projectId,activities:rows.flatMap(row=>row.activities||[])}).entries;return `<div class="pane-heading"><h2>当前工作</h2>${btn('browse-tools','查看可用工具','grid','ghost compact')}</div><section class="work-section"><h3>活动任务</h3>${active.length?active.map(threadChip).join(''):'<p class="work-empty">当前没有正在执行的任务。</p>'}</section><section class="work-section"><h3>${esc(data?.thread?.id===state.threadId?'主对话':data?.thread?.title||'任务')}的工具与结果</h3>${latest?workSummaryView(latest):'<p class="work-empty">执行后，使用中的工具和结果会出现在这里。</p>'}</section><section class="work-section"><div class="row between"><h3>最近产物</h3>${btn('open-library','Library','book','ghost compact')}</div>${assets.length?assets.map(a=>`<button class="work-asset" data-action="${esc(a.action)}" data-id="${esc(a.id)}">${icon('file')}<span>${esc(a.name||a.path?.split('/').at(-1)||'产物')}</span>${icon('chevron')}</button>`).join(''):'<p class="work-empty">尚无已登记产物。</p>'}</section>`;}


function projectSettingsPane(){const p=project();return p?`<div class="pane-heading"><h2>项目设置</h2>${btn('project-details','编辑','edit','compact')}</div><div class="setting-section"><h3>名称</h3><p class="setting-project-name">${esc(p.name)}</p></div><div class="setting-section"><h3>文件夹</h3><p class="setting-folder">${esc(p.folderPath||'未绑定文件夹')}</p></div><div class="setting-section"><div class="row between"><h3>项目指令</h3>${btn('edit-instructions','编辑','edit','compact')}</div><p class="setting-instructions">${esc(p.instructions||'尚未添加')}</p></div>`:empty('没有打开的项目','','new-project','新建项目');}
document.addEventListener('pointerdown',e=>{if(!e.target.closest('#panel-resizer'))return;const x=e.clientX,start=$('#workspace-panel').getBoundingClientRect().width;document.body.classList.add('resizing');const move=ev=>{const w=Math.max(360,Math.min($('#workspace-body').clientWidth-330,start+x-ev.clientX));document.documentElement.style.setProperty('--pane-width',w+'px');};const up=()=>{document.body.classList.remove('resizing');document.removeEventListener('pointermove',move);document.removeEventListener('pointerup',up);};document.addEventListener('pointermove',move);document.addEventListener('pointerup',up);});
document.addEventListener('keydown',e=>{if(e.key==='Enter'&&e.target.matches('input#codex-model-select,input#side-codex-model-select')){e.preventDefault();e.target.dispatchEvent(new Event('change',{bubbles:true}));return;}if(e.target.id==='panel-resizer'&&['ArrowLeft','ArrowRight'].includes(e.key)){e.preventDefault();const w=$('#workspace-panel').getBoundingClientRect().width+(e.key==='ArrowLeft'?30:-30);document.documentElement.style.setProperty('--pane-width',Math.max(360,Math.min($('#workspace-body').clientWidth-330,w))+'px');}});


function approvalView(a,scope='inline'){if(a.kind==='question')return questionApprovalView(a,scope);const thread=state.data.threads.find(t=>t.id===a.threadId),p=state.data.projects.find(p=>p.id===a.projectId);return renderApprovalCard(a,{threadTitle:thread?.kind==='worker'?thread.title:'',projectFolder:p?.folderPath||'',technicalOpen:Boolean(state.approvalDetailsOpen?.[a.id]),scope});}
const textFileAccept='.txt,.md,.markdown,.json,.csv,.tsv,.yaml,.yml,.xml,.py,.js,.mjs,.cjs,.ts,.tsx,.jsx,.html,.css,.log,.c,.cpp,.cc,.h,.hpp,.ino,.rst,.toml,.ini,.sh,.sql';
function autoGrow(el){el.style.height='auto';el.style.height=Math.min(220,Math.max(35,el.scrollHeight))+'px';el.style.overflowY=el.scrollHeight>220?'auto':'hidden';}
function updateProjectSubmit(){const f=$('#project-form'),button=$('[form="project-form"][type="submit"]');if(f&&button)button.disabled=!f.elements.name.value.trim()||!f.elements.folderPath.value.trim().startsWith('/');}
function chooseProjectFolder(){const bridge=window.webkit?.messageHandlers?.syspilot,input=$('#project-folder');if(!input||input.readOnly)return;if(!bridge){input.focus();toast('请在路径框粘贴现有文件夹的绝对路径');return;}const requestId='folder-'+crypto.randomUUID();state.folderRequest=requestId;bridge.postMessage({type:'choose-project-folder',requestId});}
window.syspilotFolderSelected=result=>{if(!result||result.requestId!==state.folderRequest)return;state.folderRequest=null;if(result.error){toast(result.error,true);return;}if(result.cancelled)return;const input=$('#project-folder');if(input&&typeof result.path==='string'&&result.path.startsWith('/')){input.value=result.path;updateProjectSubmit();input.focus();}};
async function stageAttachments(input,side){const key=(side?state.sideThreadId:state.threadId)||state.projectId||'new',list=state.attachments[key]||[];const staged=[];for(const file of input.files||[]){const ext='.'+file.name.split('.').at(-1).toLowerCase();if(!textFileAccept.split(',').includes(ext))throw new Error('仅支持文本、Markdown、JSON、CSV 和源码附件；图片与二进制文件尚不支持');if(file.size>500000)throw new Error('单份文本附件请控制在 500 KB 以内');const content=await file.text();if(!content.trim())throw new Error('附件内容为空');if(content.includes('\u0000'))throw new Error('附件无法作为纯文本读取');if(list.length+staged.length>=8)throw new Error('每次最多附加 8 份文件');staged.push({name:file.name,content,size:file.size});}state.attachments[key]=list.concat(staged);input.value='';if(side)renderPanel(true);else renderMain(true);}
document.addEventListener('dragover',e=>{if(e.target.closest('.project-prompt textarea'))e.preventDefault();});
document.addEventListener('drop',e=>{if(e.target.closest('.project-prompt textarea'))e.preventDefault();});


function runTitle(row){if(row.status==='queued'&&['queued','running'].includes(row.executionStatus||'queued'))return'排队中';const time=row.durationMs==null?'':formatDuration(row.durationMs),execution=row.executionStatus||row.status;if(row.durationLive){if(['waiting_tasks','waiting_job','preparing_environment','waiting_approval','reviewing','summarizing'].includes(execution))return statusText(execution)+(time?' · 本轮已用 '+time:'');return time?'Working for '+time:'Working…';}if(row.status==='completed')return time?'Worked for '+time:'已完成';if(['cancelled','canceled','stopped'].includes(row.status))return'已停止'+(time?' · '+time:'');if(row.status==='failed')return'运行失败'+(time?' · '+time:'');if(row.status==='interrupted')return'运行中断'+(time?' · '+time:'');return statusText(execution);}
function activityResultActions(a){if(a.kind==='thread'){const artifacts=Array.isArray(a.artifacts)?a.artifacts:[];return artifacts.length?`<div class="activity-result-actions">${artifacts.map(item=>{const id=typeof item==='string'?item:item?.id;return typeof id==='string'&&id.startsWith('artifact_')?btn('read-artifact',typeof item==='object'?(item.name||'查看交付产物'):'查看交付产物','file','compact',`data-id="${esc(id)}"`):'';}).join('')}</div>`:'';}const presented=toolResultPresentation(a,{artifacts:state.data.artifacts.filter(f=>f.projectId===state.projectId)});if(!presented)return '';let buttons=presented.actions.map(v=>btn(v.action,v.label,v.action==='view-nos3-job'?'grid':'file','compact',v.id?`data-id="${esc(v.id)}"`:`data-path="${esc(v.path)}"`)).join('');if(presented.data!=null){const resultKey=[state.projectId,a.runId||a.threadId,a.id].join(':');activityResults.set(resultKey,{projectId:state.projectId,title:a.label||'工具结果',data:presented.data});if(activityResults.size>4000)activityResults.delete(activityResults.keys().next().value);buttons+=btn('view-tool-data','查看数据','grid','ghost compact',`data-id="${esc(resultKey)}"`);}return buttons?`<div class="activity-result-actions">${buttons}</div>`:'';}
function activityView(a,hideThreadLink=false){if(a.type==='thread.routed')return routeReceiptView(a);return activityCardView(a,hideThreadLink);}
function routeReceiptView(a){return `<div class="route-receipt" data-route-id="${esc(a.routeId||a.id)}">${icon('link')}<span>已将你的消息转交给 ${inlineThreadLink(a.childThreadId)}${a.delivery==='queued'?' · 等待接收':''}</span></div>`;}
function compactThreadHandoffView(a){
 const thread=presentationThreads(state.thread).find(t=>t.id===a.childThreadId),returned=a.type==='thread.result',delivery=describeTaskDelivery(a,{taskTitle:thread?.title}),status=returned?delivery?.statusLabel:statusText(thread?threadExecutionStatus(thread):a.status);
 return `<p class="coordination-inline thread-handoff-compact" data-thread-id="${esc(a.childThreadId)}">${returned?'子任务交付':'已分派'} ${inlineThreadLink(a.childThreadId,thread?.title)} · ${esc(status||'待处理')}${delivery?.preview?`<span> · 子线程报告：${esc(delivery.preview)}</span>`:''}</p>`;
}

function activityCardView(a,hideThreadLink=false){const professional=describeProfessionalActivity(a),delivery=describeTaskDelivery(a,{taskTitle:presentationThreads(state.thread).find(t=>t.id===a.childThreadId)?.title}),detail=normalizeText(professional?.detail||delivery?.detail||a.detail),longThread=a.kind==='thread'&&detail.length>220,working=['running','started','queued','pending'].includes(a.status),failed=professional?.attention||['blocked','failed','error','rejected','cancelled'].includes(a.status);return `<article class="run-activity ${failed?'activity-failed':''}" data-activity-id="${esc(a.id)}"><div class="activity-line"><span class="activity-icon">${working?'<span class="pulse"></span>':icon(a.status==='waiting_approval'?'lock':['waiting_tasks','waiting_job','preparing_environment'].includes(a.status)?'clock':failed?'warning':a.kind==='thread'?'chat':'terminal')}</span><strong>${esc(professional?.title||delivery?.title||a.label||a.tool||a.type||'活动')}</strong><span class="activity-status">${esc(professional?.executionLabel||delivery?.statusLabel||statusText(a.status))}${a.repeatedFailureCount?' · '+a.repeatedFailureCount+' 次相同失败':''}</span>${!hideThreadLink&&a.childThreadId&&workerThreads().some(t=>t.id===a.childThreadId)?btn('select-thread','打开线程','chevron','ghost compact',`data-id="${esc(a.childThreadId)}"`):''}</div>${detail?`<p class="activity-detail">${esc(longThread?detail.slice(0,220)+'…':detail)}</p>${longThread?`<details class="activity-payload"><summary>完整交付摘要</summary><div class="message-body">${markdown(detail)}</div></details>`:''}`:''}${professional?.verificationLabel?`<p class="activity-verification ${professional.attention?'needs-attention':''}">${esc(professional.verificationLabel)}</p>`:''}${delivery?.rawMessage?`<details class="activity-payload"><summary>原始交接消息</summary><pre>${esc(delivery.rawMessage)}</pre></details>`:''}${a.branchStatus==='blocked'&&a.openDependencies?.length?`<div class="activity-result-actions">${a.openDependencies.map(task=>btn('select-thread',task.title||'查看未闭合子任务','chat','ghost compact',`data-id="${esc(task.threadId)}"`)).join('')}</div>`:''}${activityResultActions(a)}${a.args!==undefined||a.result!==undefined?`<details class="activity-payload"><summary>输入与实际输出</summary>${a.args!==undefined?`<pre>${esc(normalizeText(a.args))}</pre>`:''}${a.result!==undefined?`<pre>${esc(normalizeText(a.result))}</pre>`:''}</details>`:''}</article>`;}
const hiddenProgressTypes=new Set(['run.queued','run.started','run.finished','agent.started','agent.thinking','agent.completed']);
function presentationThreads(data){return mergeTaskRecords({globalThreads:state.data.threads,detail:data,projectThreads:state.projectThreads,sideThread:state.sideThread?.thread,sideThreadId:state.sideThreadId});}
function coordinationView(row){
 if(row.executionStatus==='waiting_job'){const job=row.waitingJob||row.run.waitingJob;return `<p class="coordination-inline">等待${esc(jobScopeLabel(job?.scope))}结果${job?.jobId?` · ${btn(job.jobId.startsWith('professional_')?'view-professional-job':'view-nos3-job','查看作业','','ghost compact',`data-id="${esc(job.jobId)}"`)}`:''}，返回后继续复核。</p>`;}
 const waiting=row.executionStatus==='waiting_tasks'?row.waitingFor:null;
 if(waiting?.tasks?.length)return `<p class="coordination-inline">等待${waiting.tasks.map(t=>inlineThreadLink(t.threadId,t.title)).join('、')}${waiting.mode==='any'?'任一结果':'的结果'}，返回后继续。</p>`;
 const handoff=row.run.lastHandoff;if(!handoff||!['reviewing','summarizing'].includes(row.executionStatus))return'';
 return `<p class="coordination-inline">${row.executionStatus==='summarizing'?'正在汇总':'正在复核'}${(handoff.results||[]).map(t=>inlineThreadLink(t.threadId,t.title)).join('、')}的交付。</p>`;
}

function unreviewedTaskNotice(row){if(busyStatuses.includes(row.rawStatus||row.status))return'';const ids=new Set((Array.isArray(row.run.unreviewedTaskRunIds)?row.run.unreviewedTaskRunIds:[]).filter(id=>typeof id==='string'&&id.trim()));return ids.size?`<p class="run-review-pending" role="status" data-unreviewed-task-count="${ids.size}">有 ${ids.size} 项子任务结果尚未复核</p>`:'';}
function coordinationThreadIds(row){return new Set(((row.executionStatus==='waiting_tasks'?row.waitingFor?.tasks:['reviewing','summarizing'].includes(row.executionStatus)?row.run.lastHandoff?.results:[])||[]).map(t=>t.threadId));}
function presentationRows(data){return buildRunPresentation({messages:data.messages||[],runs:[...new Map([...(state.data.runs||[]),...(data.runs||[])].map(r=>[r.id,r])).values()],events:data.events||[],agents:[...new Map([...(state.data.agents||[]).filter(a=>!a.projectId||a.projectId===(data.thread?.projectId||state.projectId)),...(data.agents||[])].map(a=>[a.id,a])).values()],threadId:data.thread?.id,childThreads:presentationThreads(data),approvals:data.approvals||[],eventHistory:data.eventHistory,nowMs:Date.now()});}
function runWorkView(row){return visibleRunWork(row,{hasResult:a=>Boolean(toolResultPresentation(a,{artifacts:state.data.artifacts})?.actions?.length),resultKey:a=>{const action=toolResultPresentation(a,{artifacts:state.data.artifacts})?.actions?.[0];return action?action.action+':'+(action.id||action.path||''):null;}});}
function workSummaryView(row){const visible=runWorkView(row),destinations=new Set(visible.activities.flatMap(a=>(toolResultPresentation(a,{artifacts:state.data.artifacts})?.actions||[]).map(v=>v.action+':'+(v.id||v.path||'')))),allDestinations=new Set((row.activities||[]).flatMap(a=>(toolResultPresentation(a,{artifacts:state.data.artifacts})?.actions||[]).map(v=>v.action+':'+(v.id||v.path||'')))),summary=summarizeChatArtifacts(state.data.artifacts,{projectId:state.projectId,runId:row.runId,activities:row.activities||[]}),assets=summary.entries.filter(a=>!(a.kind==='job'?allDestinations:destinations).has(a.action+':'+a.id));return `<div class="run-visible-work" aria-label="当前执行与交付">${coordinationView(row)}${visible.routes.map(activityView).join('')}${visible.activities.map(a=>activityView(a)).join('')}${assets.length?`<div class="run-artifacts" aria-label="本轮产物">${assets.map(a=>`<button class="work-asset" data-action="${esc(a.action)}" data-id="${esc(a.id)}">${icon(a.kind==='job'?'grid':'file')}<span>${esc(a.name)}</span>${icon('chevron')}</button>`).join('')}</div>`:''}${visible.routineCount?`<div class="work-record-links">${btn('open-engineering-plan','工程计划','model','ghost compact')}${btn('open-engineering-records','工程记录','link','ghost compact')}</div>`:''}</div>`;}

function completedTurnLinks(row){const entries=completedTurnEntries(row,{artifacts:state.data.artifacts,projectId:state.projectId}),link=v=>`<button data-action="${esc(v.action)}" ${v.id?`data-id="${esc(v.id)}"`:`data-path="${esc(v.path)}"`}>${icon(v.kind==='job'?'grid':'file')}<span>${esc(v.name)}</span></button>`;return `<div class="completed-turn-links">${entries.files.map(link).join('')}${entries.allFiles.length>entries.files.length?`<button data-action="open-library">Library · ${entries.allFiles.length}</button>`:''}${entries.hasPlan?'<button data-action="open-engineering-plan">工程计划</button>':''}${entries.jobs.length?`<details class="completed-result-links"><summary>${entries.counts.jobs} 次求解${icon('chevron')}</summary><div>${entries.jobs.map(job=>`<div class="completed-result-row ${job.attention?'needs-attention':''}">${link(job)}<span>${esc([job.state,job.verification].filter(Boolean).join(' · '))}</span></div>`).join('')}</div></details>`:''}</div>`;}
function runClockView(row,attention){return `<span class="run-summary-icon">${row.durationLive&&['running','reviewing','summarizing'].includes(row.executionStatus)?'<span class="pulse"></span>':icon(row.executionStatus==='waiting_approval'?'lock':['waiting_tasks','waiting_job','preparing_environment'].includes(row.executionStatus)||row.status==='queued'?'clock':attention?'warning':'check')}</span><span class="run-clock" data-run-clock="${esc(row.runId)}" data-run-status="${esc(row.status)}" data-run-execution-status="${esc(row.executionStatus)}" data-started-at="${esc(row.startedAt||'')}">${esc(runTitle(row))}</span>${row.automatic?'<span class="run-auto-label">自动恢复</span>':''}`;}
function conversationRows(data,main=false){if(!data)return'';const rows=presentationRows(data),returnedRuns=new Set(rows.filter(row=>row.kind==='message'&&row.activity?.type==='thread.result').map(row=>row.activity.runId).filter(Boolean));return rows.map(row=>{
 if(row.kind==='message'){
  if(row.activity?.type==='thread.routed')return routeReceiptView(row.activity);
  if(row.activity?.childThreadId)return compactThreadHandoffView(row.activity);
  return row.activity?`<details class="thread-return-notice compact-handoff"><summary>Thread 更新${icon('chevron')}</summary>${activityView(row.activity)}</details>`:row.origin?internalMessageView(row.message,row.origin):messageView(row.message,main);
 }
 const actualRun=data.runs?.find(r=>r.id===row.runId),opened=Boolean(state.expandedRuns[row.runId]),children=row.childThreads||[],attention=['failed','cancelled','canceled','interrupted'].includes(row.status),visible=runWorkView(row),disclosure=chatTurnDisclosure(row,visible),live=disclosure.live;
 const statusThreads=coordinationThreadIds(row);
 const handoffs=main?compactThreadHandoffs(row).filter(a=>a.type==='thread.result'||!statusThreads.has(a.childThreadId)&&!returnedRuns.has(a.runId)).map(compactThreadHandoffView).join(''):'';
 const progressIds=new Set(disclosure.messages.map(m=>m.id));
 const timeline=[...(row.internalMessages||[]).map(({message,origin},index)=>({at:message.createdAt||row.startedAt||'',index:index-100000,html:internalMessageView(message,origin)})),...(row.processMessages||[]).filter(m=>!progressIds.has(m.id)).map((m,index)=>({at:m.createdAt||row.startedAt||'',index,html:messageView(m,false)})),...disclosure.processActivities.filter(a=>!hiddenProgressTypes.has(a.type)&&!(main&&a.kind==='thread'&&a.childThreadId)).map((a,index)=>({at:a.startedAt||a.finishedAt||a.observedAt||'',index:index+100000,html:activityView(a,Boolean(a.childThreadId&&children.some(t=>t.id===a.childThreadId)))}))].sort((a,b)=>a.at.localeCompare(b.at)||a.index-b.index);
 const readFailures=disclosure.foldedReadFailureCount?` · 资料/文件读取失败 ${disclosure.foldedReadFailureCount} 次`:'';
 const process=`<details class="run-process ${live?'':'completed-process'} ${attention?'run-attention':''}" data-run-id="${esc(row.runId)}" ${opened?'open':''}><summary>${live?`<span>过程记录${timeline.length?' · '+timeline.length:''}${visible.recoveredCount?' · '+visible.recoveredCount+' 项错误已恢复':''}${readFailures}</span>`:`${runClockView(row,attention)}${readFailures?`<span>${readFailures}</span>`:''}`}${icon('chevron')}</summary><div class="run-process-body">${timeline.length?timeline.map(t=>t.html).join(''):'<p class="run-empty-process">没有其他过程记录。</p>'}${row.eventHistory?.truncated?'<p class="run-history-note">部分早期活动未包含在当前记录中。</p>':''}</div></details>`;
 return `<section class="run-turn" data-run-id="${esc(row.runId)}" data-run-status="${esc(row.status)}" data-run-execution-status="${esc(row.executionStatus)}">${(row.userMessages||[]).map(m=>messageView(m,main)).join('')}${live?`<div class="run-status-line" role="status">${runClockView(row,attention)}</div>${disclosure.messages.map(m=>`<div class="run-current-update">${messageView(m)}</div>`).join('')}<div class="run-visible-work">${coordinationView(row)}${handoffs}${disclosure.routes.map(routeReceiptView).join('')}${disclosure.publicActivities.map(a=>activityView(a)).join('')}</div>`:handoffs+disclosure.routes.map(routeReceiptView).join('')}${live?completedTurnLinks(row):''}${process}${attention?`<p class="run-outcome">${esc(row.status==='failed'?'本轮失败'+(actualRun?.error?'：'+actualRun.error:'，未生成完成答复。'):row.status==='interrupted'?'本轮因服务中断而停止；可发送消息继续。':'本轮已停止。')}</p>`:''}${row.finalMessageMissing?'<p class="run-history-note">未保存可匹配的最终回复，可展开查看运行记录。</p>':''}${row.finalMessage?`<div class="run-final">${messageView(row.finalMessage,main)}</div>`:''}${live?'':completedTurnLinks(row)}${unreviewedTaskNotice(row)}</section>`;
 }).join('');}

function tickRunClocks(){if(document.hidden)return;$$('[data-run-clock]').forEach(el=>{if(!busyStatuses.includes(el.dataset.runStatus)||el.dataset.runStatus==='queued')return;const start=Date.parse(el.dataset.startedAt);if(Number.isFinite(start))el.textContent=runTitle({status:el.dataset.runStatus,executionStatus:el.dataset.runExecutionStatus,durationLive:true,durationMs:Math.max(0,Date.now()-start)});});}
