document.addEventListener('toggle',e=>{if(e.target.isConnected&&e.target.matches?.('.run-process'))state.expandedRuns[e.target.dataset.runId]=e.target.open;},true);
document.addEventListener('toggle',e=>{if(e.target.isConnected&&e.target.matches?.('.internal-message'))state.expandedInternalMessages[e.target.dataset.messageId]=e.target.open;},true);
document.addEventListener('click',e=>{const summary=e.target.closest('.thread-group>summary');if(!summary)return;e.preventDefault();const details=summary.parentElement;if(details.dataset.threadCount==='0')return;details.open=!details.open;state.threadGroupOpen[threadGroupKey(details.dataset.threadProject,details.dataset.threadGroup)]=details.open;});
document.addEventListener('toggle',e=>{const details=e.target;if(details.isConnected&&details.matches?.('.thread-group[data-thread-project]')&&details.dataset.threadCount!=='0')state.threadGroupOpen[threadGroupKey(details.dataset.threadProject,details.dataset.threadGroup)]=details.open;},true);

