function generalSettings(){const g=state.settings;return `<h2 class="settings-heading">常规</h2><section class="settings-group"><h3>权限</h3><div class="settings-card"><div class="settings-row"><div><label for="default-permission-setting">默认权限</label><p>未单独设置权限时使用，可在聊天输入框更改。</p></div><select id="default-permission-setting"><option value="manual" ${g.defaultPermissionMode==='manual'?'selected':''}>Manual</option><option value="auto" ${g.defaultPermissionMode==='auto'?'selected':''}>Auto</option></select></div><div class="settings-card-note"><strong>Manual</strong>：修改文件、模型或运行仿真前询问。<br><strong>Auto</strong>：自动读写、建模和运行项目内命令与测试；额外权限按运行时策略询问，桌面操作单独授权。</div></div></section><section class="settings-group"><h3>外观</h3><div class="settings-card"><div class="settings-row"><div><label for="appearance-setting">主题</label></div><select id="appearance-setting">${[['system','跟随系统'],['light','明亮'],['dark','深色']].map(([id,label])=>`<option value="${id}" ${g.appearance===id?'selected':''}>${label}</option>`).join('')}</select></div></div></section>`;}
function computerSettings(){const c=state.computer,b=c.browser||{},d=c.desktop||{},enabled=d.status?.startsWith('enabled');return `<div class="settings-page-header"><h2 class="settings-heading">Computer</h2>${btn('computer-refresh','刷新','refresh','compact')}</div><section class="settings-group"><h3>连接</h3><div class="settings-card"><div class="settings-row"><div><strong>独立浏览器</strong><p>${b.available?'用于操作网页。':'安装浏览器支持后可用。'}</p></div><span class="badge ${b.available?'green':''}">${b.available?'可用':'不可用'}</span></div><div class="settings-row"><div><strong>本机桌面</strong><p>${!d.available?'仅支持 macOS。':enabled?'系统权限将在首次操作时检查。':'用于操作本机应用，需要 macOS 屏幕录制和辅助功能权限。'}</p></div><span class="badge ${enabled?'green':''}">${!d.available?'不支持':enabled?'已开启':'未开启'}</span></div></div></section>${project()?`<div class="settings-computer-actions">${btn('settings-open-computer','打开 Computer','external')}${d.available?(enabled?btn('desktop-disable','关闭桌面连接','lock'):btn('desktop-enable','启用桌面连接','lock')):''}</div>`:'<p class="settings-intro">打开项目后可使用 Computer。</p>'}`;}
