function updateProviderFields(){const f=$('#provider-form');if(!f)return;const existing=state.data.providers.find(p=>p.id===f.dataset.edit),isolated=existing?.name==='Codex · 隔离 Linux Agent';if(isolated)f.elements.type.value='codex-app-server';f.elements.type.disabled=isolated;const type=f.elements.type.value,codex=type==='codex-app-server'||type==='codex-cli',claude=type==='claude-agent',offline=type==='demo',model=f.elements.model,url=f.elements.baseUrl;model.required=isolated||!offline&&!codex&&!claude||codex&&Boolean(url.value.trim());url.required=isolated;f.elements.apiKey.required=isolated&&!existing.configured;model.placeholder=isolated?'填写 Responses 服务支持的模型 ID':codex?'留空使用本机默认模型':claude?'留空使用 Claude 默认模型':'填写服务支持的模型 ID';url.placeholder=isolated?'https://api.openai.com/v1':codex?'留空复用本机 Codex 登录':claude?'https://api.anthropic.com':providerDefaults[type]||'';$('#provider-type-note').textContent=isolated?'原生 Codex 在隔离 Linux 中运行，无法读取本机登录。请填写以下三项。':codex?'使用本机 Codex 登录和工具。':claude?'使用 Claude Code 的原生工具和会话。':offline?'确定性离线示例，不调用实时模型。':'Manta 使用 Agents SDK 管理通用 Agent 与工具调用，并通过所选模型 API 请求模型。';$('#provider-model-hint').textContent=isolated?'填写此 Responses 服务支持的模型 ID。':codex?'自定义 Responses 端点时，请填写该服务支持的模型。':claude?'可按你的 Anthropic 服务指定模型。':offline?'确定性离线示例，不调用实时模型。':'此类型必须填写模型名称。';$('#provider-url-hint').textContent=isolated?'填写可从隔离 Linux 访问的 Responses API 根地址，例如 https://api.openai.com/v1。':codex?'自定义服务请填写 Responses 端点根地址，并按该服务要求配置凭据。':claude?'可选的 Anthropic 兼容根地址；留空使用官方服务。':'留空使用上方提示的默认地址。';$('#provider-auth-note').textContent=isolated?'密钥仅保存在本次隔离服务进程的内存中；重启后需重填。':codex?'使用本机登录时无需填写。':claude?'填写 Anthropic API Key，或指定环境变量。':'API Key 仅在当前运行期间保存。';for(const el of $$('[data-provider-field]',f))el.hidden=offline;$('#provider-auth-note').hidden=offline;}
const questionSecrets=new Map();
function findApproval(id){return(state.data.approvals||[]).find(a=>a.id===id)||(state.thread?.approvals||[]).find(a=>a.id===id)||(state.sideThread?.approvals||[]).find(a=>a.id===id);}
function questionKey(q,index){return String(q.id||q.question||q.header||'question-'+index);}
function questionDraft(a,index){const q=a.args.questions[index],cache=q.isSecret?questionSecrets.get(a.id):state.answerDrafts[a.id];return cache?.[index]||{selected:[],freeText:''};}
function questionApprovalView(a,scope){const questions=a.args?.questions||[];return `<section class="inline-approval question-approval" data-approval-id="${esc(a.id)}"><div class="question-approval-heading">${icon('chat')}需要你的答复</div><form class="question-form" data-question-approval="${esc(a.id)}">${questions.map((q,index)=>{const draft=questionDraft(a,index),key=questionKey(q,index),prefix='answer-'+scope+'-'+a.id+'-'+index,options=q.options||[],other=q.isOther!==false||!options.length;return `<fieldset data-question-index="${index}"><legend>${q.header?`<span class="question-header">${esc(q.header)}</span>`:''}${esc(q.question||'请补充信息')}</legend>${q.multiSelect?'<p class="question-hint">可选择多项</p>':''}${options.map((o,n)=>`<label class="question-option" for="${esc(prefix+'-'+n)}"><input id="${esc(prefix+'-'+n)}" data-question-choice="true" data-question-index="${index}" type="${q.multiSelect?'checkbox':'radio'}" name="question-${index}" value="${esc(o.label)}" ${draft.selected.includes(o.label)?'checked':''}><span><strong>${esc(o.label)}</strong>${o.description?`<small>${esc(o.description)}</small>`:''}</span></label>`).join('')}${other?`<label class="question-free-label" for="${esc(prefix+'-text')}">${options.length?'其他答复':'你的答复'}<input id="${esc(prefix+'-text')}" data-question-free="true" data-question-index="${index}" type="${q.isSecret?'password':'text'}" autocomplete="off" ${q.isSecret?'data-question-secret="true"':''} placeholder="${q.isSecret?'仅用于本次答复':'填写你的答复'}" ${q.isSecret?'':`value="${esc(draft.freeText)}"`}></label>`:''}</fieldset>`;}).join('')}<div class="question-form-actions">${btn('reject-approval','取消本次请求','','compact',`data-id="${esc(a.id)}"`)}<button type="submit" class="button primary compact" ${questionReady(a)?'':'disabled'}>提交答复</button></div></form></section>`;}
function questionReady(a){return Boolean(a.args?.questions?.length)&&a.args.questions.every((q,i)=>{const d=questionDraft(a,i);return d.selected.length||d.freeText.trim();});}
function captureQuestionInput(el){const form=el.closest('.question-form'),a=findApproval(form?.dataset.questionApproval);if(!a)return;const index=Number(el.dataset.questionIndex),q=a.args.questions[index];if(!q)return;const field=el.closest('fieldset'),previous=questionDraft(a,index),next={selected:[...previous.selected],freeText:previous.freeText};if(el.dataset.questionFree){next.freeText=el.value;if(!q.multiSelect&&el.value.trim()){next.selected=[];$$('[data-question-choice]',field).forEach(input=>input.checked=false);}}else if(el.dataset.questionChoice){next.selected=$$('[data-question-choice]:checked',field).map(input=>input.value);if(!q.multiSelect&&next.selected.length){next.freeText='';const free=$('[data-question-free]',field);if(free)free.value='';}}const cache=q.isSecret?(questionSecrets.get(a.id)||{}):(state.answerDrafts[a.id]||{});cache[index]=next;if(q.isSecret)questionSecrets.set(a.id,cache);else state.answerDrafts[a.id]=cache;const submit=$('[type="submit"]',form);if(submit)submit.disabled=!questionReady(a);}
function restoreQuestionSecrets(){$$('.question-form').forEach(form=>{const a=findApproval(form.dataset.questionApproval);if(!a)return;$$('[data-question-secret]',form).forEach(input=>{input.value=questionDraft(a,Number(input.dataset.questionIndex)).freeText;});});}
function pruneQuestionDrafts(){const pending=new Set((state.data.approvals||[]).filter(a=>a.status==='pending').map(a=>a.id));for(const id of Object.keys(state.answerDrafts))if(!pending.has(id))delete state.answerDrafts[id];for(const id of questionSecrets.keys())if(!pending.has(id))questionSecrets.delete(id);}
async function submitQuestionAnswers(form){const id=form.dataset.questionApproval,a=findApproval(id);if(!a||!questionReady(a))throw new Error('请回答每一个问题');const answers=Object.fromEntries(a.args.questions.map((q,index)=>{const d=questionDraft(a,index),values=[...d.selected,...(d.freeText.trim()?[d.freeText.trim()]:[])];return [questionKey(q,index),{answers:q.multiSelect?values:values.slice(-1)}];}));await post('/api/approvals/'+encodeURIComponent(id),{decision:'approve',answers});delete state.answerDrafts[id];questionSecrets.delete(id);await refresh();if(state.modal?.title==='需要你的答复')showApprovals();toast('答复已提交');}

