  const target=event.target;if(!(target instanceof HTMLDetailsElement)||!target.isConnected||!target.hasAttribute('data-approval-technical'))return;
  state.approvalDetailsOpen||={};state.approvalDetailsOpen[target.dataset.approvalTechnical]=target.open;
