async function copyText(text){
  if(navigator.clipboard?.writeText){try{await navigator.clipboard.writeText(text);return;}catch{}}
  const input=document.createElement('textarea');input.value=text;input.style.position='fixed';input.style.opacity='0';input.setAttribute('readonly','');document.body.append(input);const previous=document.activeElement;
  try{input.select();if(!document.execCommand('copy'))throw new Error('无法复制，请选择命令后手动复制');}finally{input.remove();previous?.focus?.({preventScroll:true});}
}

function integrationsView(compact=false){return renderIntegrations({project:project(),projects:state.data.projects,status:state.integrations.for===state.projectId?state.integrations.status:'loading',error:state.integrations.error,data:state.integrations.for===state.projectId?state.integrations.data:null},{compact});}
async function loadIntegrations({force=false}={}){
  const projectId=state.projectId;if(!projectId)return;
  if(!force&&state.integrations.for===projectId&&integrationRequests.has(projectId))return integrationRequests.get(projectId);
  if(!force&&state.integrations.for===projectId&&state.integrations.status==='ready'&&Date.now()-state.integrations.loadedAt<5000)return state.integrations.data;
  const sequence=++integrationSequence;
  state.integrations={...state.integrations,for:projectId,request:sequence,status:state.integrations.data&&state.integrations.for===projectId?'refreshing':'loading',error:''};renderIntegrationSurface();
  const pending=(async()=>{
    try{const data=await api('/api/projects/'+encodeURIComponent(projectId)+'/integrations');if(projectId!==state.projectId||state.integrations.request!==sequence)return;if(data.projectId&&data.projectId!==projectId)throw Error('服务返回了其他项目的工具连接');state.integrations={for:projectId,request:sequence,status:'ready',data,error:'',loadedAt:Date.now()};return data;}
    catch(error){if(projectId===state.projectId&&state.integrations.request===sequence)state.integrations={for:projectId,request:sequence,status:'error',data:null,error:error.message,loadedAt:0};throw error;}
    finally{if(integrationRequests.get(projectId)===pending)integrationRequests.delete(projectId);if(projectId===state.projectId)renderIntegrationSurface();}
  })();
  integrationRequests.set(projectId,pending);return pending;
}
function renderIntegrationSurface(){if(state.view==='settings'&&state.settingsSection==='integrations'){state.settingsKey='';renderSettings();}else if(['integrations','tools'].includes(state.panel))renderPanel(true);}
function requireIntegrationProject(projectId){if(!projectId||projectId!==state.projectId||!project())throw Error('项目已切换，请在当前项目重新打开连接配置');return projectId;}
function connectorInProject(id){const rows=state.integrations.for===state.projectId?state.integrations.data?.connectors:[];return Array.isArray(rows)?rows.find(row=>row.id===id):undefined;}
function openConnector(id){const projectId=requireIntegrationProject(state.projectId),config=id?connectorInProject(id):{};if(id&&!config)throw Error('连接不在当前项目中，请刷新后重试');openModal(id?'编辑 MCP 连接':'添加 MCP 连接',renderConnectorForm(config,projectId),formFooter('mcp-connector-form',id?'保存':'添加'));state.modal.integrationProject=projectId;updateConnectorFields();}
function updateConnectorFields(){const form=$('#mcp-connector-form');if(!form)return;const transport=$('#mcp-transport',form).value;$$('[data-mcp-transport]',form).forEach(section=>{section.hidden=section.dataset.mcpTransport!==transport;$$('input,textarea',section).forEach(field=>field.disabled=section.hidden);});const url=$('#mcp-url',form),command=$('#mcp-command',form);url.required=transport==='http';command.required=transport==='stdio';}
async function saveConnectorForm(form,values){
  const projectId=requireIntegrationProject(form.dataset.project),existing=form.dataset.edit?connectorInProject(form.dataset.edit):undefined;
  const {config,runtimeKey}=parseConnectorForm(values,{editId:form.dataset.edit,existing});
  await post('/api/projects/'+encodeURIComponent(projectId)+'/connectors',{...config,...(runtimeKey?{runtimeKey}:{})});
  if(projectId!==state.projectId)return;closeModal();await loadIntegrations({force:true});toast('MCP 连接已保存');
}
function openWorkerForm(){const projectId=requireIntegrationProject(state.projectId),worker=state.integrations.data?.nos3?.worker||{};openModal('NOS3 远程 Worker',renderWorkerForm(worker,projectId),formFooter('nos3-worker-form'));state.modal.integrationProject=projectId;}
async function saveWorkerForm(form,values){
  const projectId=requireIntegrationProject(form.dataset.project);let endpoint;try{endpoint=new URL(String(values.endpoint||'').trim());}catch{throw Error('请输入有效的 HTTPS Worker 地址');}
  if(endpoint.protocol!=='https:'||endpoint.username||endpoint.password||endpoint.search||endpoint.hash)throw Error('Worker 地址必须使用 HTTPS，且不能包含账号、查询参数或片段');
  const tokenEnv=String(values.tokenEnv||'').trim();if(tokenEnv&&!/^MANTA_NOS3_[A-Z0-9_]+$/.test(tokenEnv))throw Error('令牌环境变量须使用 MANTA_NOS3_ 前缀');
  await api('/api/projects/'+encodeURIComponent(projectId)+'/nos3/worker',{method:'PUT',body:JSON.stringify({worker:{type:'remote-https',endpoint:endpoint.href,...(tokenEnv?{tokenEnv}:{})}})});
  if(projectId!==state.projectId)return;closeModal();await loadIntegrations({force:true});toast('NOS3 Worker 已保存');
}
async function integrationAction(action,id,el){
  if(!integrationActions.has(action))return false;
  if(action==='open-integrations'){openPane('integrations');await loadIntegrations({force:true});return true;}
  if(action==='configure-integrations'){await openGlobalSettings('integrations');return true;}
  if(action==='refresh-integrations'){await loadIntegrations({force:true});return true;}
  const projectId=requireIntegrationProject(state.projectId),base='/api/projects/'+encodeURIComponent(projectId);
  if(action==='add-mcp-connector'){openConnector();return true;}
  if(action==='edit-mcp-connector'){openConnector(id);return true;}
  if(action==='edit-nos3-worker'){openWorkerForm();return true;}
  if(action==='delete-mcp-connector'){
    const config=connectorInProject(id);if(!config)throw Error('连接不在当前项目中');
    confirmModal('移除 MCP 连接',`移除「${config.name}」的项目配置，并关闭该连接。`,async()=>{requireIntegrationProject(projectId);await api(base+'/connectors/'+encodeURIComponent(id),{method:'DELETE'});await loadIntegrations({force:true});toast('连接已移除');});return true;
  }
  if(action==='remove-nos3-worker'){confirmModal('断开 NOS3 Worker','后续构建和集成仿真将无法使用此 Worker。已有作业和证据会保留。',async()=>{requireIntegrationProject(projectId);await api(base+'/nos3/worker',{method:'PUT',body:JSON.stringify({worker:null})});await loadIntegrations({force:true});toast('Worker 已断开');});return true;}
  el.disabled=true;
  try{
    if(action==='test-mcp-connector'||action==='discover-mcp-tools'){
      if(!connectorInProject(id))throw Error('连接不在当前项目中');
      const result=action==='test-mcp-connector'?await post(base+'/connectors/'+encodeURIComponent(id)+'/test'):await api(base+'/connectors/'+encodeURIComponent(id)+'/tools');
      if(projectId!==state.projectId)return true;await loadIntegrations({force:true});if(projectId!==state.projectId)return true;
      const summary=action==='test-mcp-connector'?`<p class="integration-test-summary">${esc(result.server?.name||'MCP 服务')}${result.server?.version?' · '+esc(result.server.version):''} · 连接成功</p>`:'';
      openModal(action==='test-mcp-connector'?'连接测试结果':'MCP 工具',summary+renderToolCatalog(result),btn('close-modal','完成','','primary'),true);state.modal.integrationProject=projectId;
    } else if(action==='prepare-nos3-environment'||action==='stop-nos3-environment'){
      toast(action==='prepare-nos3-environment'?'正在准备隔离的 Linux 环境…':'正在停止虚拟机…');
      await post(base+'/nos3/environment/'+(action==='prepare-nos3-environment'?'prepare':'stop'));if(projectId!==state.projectId)return true;await loadIntegrations({force:true});toast(action==='prepare-nos3-environment'?'Linux 工程环境已就绪':'虚拟机已停止');
    } else if(action==='view-nos3-job'){
      await openWorkspaceJob(id);
    } else if(action==='cancel-nos3-job'){
      await post(base+'/nos3/jobs/'+encodeURIComponent(id)+'/cancel');if(projectId!==state.projectId)return true;await loadIntegrations({force:true});toast('已请求停止作业');
    }
  }finally{if(el.isConnected)el.disabled=false;}
  return true;
}

document.addEventListener('change',e=>{if(e.target.id==='capability-stage'){state.capabilityStage=e.target.value;renderPanel(true);}});
// Only our current, same-origin embedded engineering page may navigate the project workspace.
window.addEventListener('message',e=>{const frame=document.querySelector('.engineering-frame');if(e.origin!==location.origin||e.source!==frame?.contentWindow||e.data?.type!=='manta:open-file'||e.data.projectId!==state.projectId)return;openWorkspacePath(e.data.path).catch(error=>toast(error.message,true));});

// A standalone engineering page can return to the same project/file entrypoint.
const initialFile=initialLocation.get('file');
if(initialFile){const openInitial=setInterval(()=>{if(!state.loading&&state.projectId){clearInterval(openInitial);openWorkspacePath(initialFile).catch(e=>toast(e.message,true));}},100);setTimeout(()=>clearInterval(openInitial),15000);}
